    box-shadow: var(--ew-structure-tooltip-shadow, none);
    opacity: 0; pointer-events: none; transition: opacity 120ms ease;
  }
  .ew-tooltip:hover .ew-tooltip__tip, .ew-tooltip:focus-within .ew-tooltip__tip { opacity: 1; }
